begin;
select no_plan();
insert into auth.users(id,email,email_confirmed_at,phone,phone_confirmed_at,raw_app_meta_data) values
 ('f7500000-0000-4000-8000-000000000001','request-staff@example.test',now(),null,null,'{}'),
 ('f7500000-0000-4000-8000-000000000002',null,null,'46700007502',now(),'{}'),
 ('f7500000-0000-4000-8000-000000000003',null,null,'46700007503',now(),'{}'),
 ('f7500000-0000-4000-8000-000000000004','request-worker@example.test',now(),null,null,'{"komisio_push_worker":true}');
insert into auth.sessions(id,user_id,aal) values
 ('f7500000-0000-4000-8000-000000000012','f7500000-0000-4000-8000-000000000002','aal1'),
 ('f7500000-0000-4000-8000-000000000013','f7500000-0000-4000-8000-000000000003','aal1');
set local role authenticated;
set local request.jwt.claims='{"sub":"f7500000-0000-4000-8000-000000000001","role":"authenticated"}';
select set_config('test.tenant',create_tenant('Synthetic request push','synthetic-request-push',gen_random_uuid())::text,true);
select publish_seller_agreement(current_setting('test.tenant')::uuid,'f7500000-0000-4000-8000-000000000101',null,'Synthetic agreement','Synthetic terms','sv',true);
reset role;
update platform_settings set central_app_tenant_id=current_setting('test.tenant')::uuid;
set local role authenticated;
set local request.jwt.claims='{"sub":"f7500000-0000-4000-8000-000000000002","session_id":"f7500000-0000-4000-8000-000000000012","role":"authenticated"}';
select throws_like($$select set_my_push_device('f7500000-0000-4000-8000-000000000021',repeat('a',64),gen_random_uuid(),0,'ExpoPushToken[synthetic_external]','ios','sv',true)$$,'%FORBIDDEN%','phone verification alone does not subscribe an unrelated account');
select reserve_external_item_photo('f7500000-0000-4000-8000-000000000201',repeat('a',64),100);
insert into storage.objects(bucket_id,name) values('external-item-photos','f7500000-0000-4000-8000-000000000002/f7500000-0000-4000-8000-000000000201.jpg');
select submit_external_item_request('f7500000-0000-4000-8000-000000000301',current_setting('test.tenant')::uuid,'Jacket','','good','',40000,'SEK',array['f7500000-0000-4000-8000-000000000201']::uuid[],'SE','seller_amount');
select is(set_my_push_device('f7500000-0000-4000-8000-000000000021',repeat('a',64),'f7500000-0000-4000-8000-000000000031',0,'ExpoPushToken[synthetic_external]','ios','sv',true)->>'enabled','true','phone request owner consents without email or seller membership');
select is(my_push_device('f7500000-0000-4000-8000-000000000021',repeat('a',64))->>'enabled','true','phone owner can read device consent');
select throws_ok($$select seller_push_candidates()$$,'42501','FORBIDDEN','request owner cannot read the worker queue');
select throws_like($$select * from komisio_private.seller_push_devices$$,'%permission denied%','tokens remain private');
set local request.jwt.claims='{"sub":"f7500000-0000-4000-8000-000000000001","role":"authenticated"}';
select issue_external_item_offer(current_setting('test.tenant')::uuid,'f7500000-0000-4000-8000-000000000401','f7500000-0000-4000-8000-000000000301',null,40000,100000,'f7500000-0000-4000-8000-000000000101');
select issue_external_item_offer(current_setting('test.tenant')::uuid,'f7500000-0000-4000-8000-000000000401','f7500000-0000-4000-8000-000000000301',null,40000,100000,'f7500000-0000-4000-8000-000000000101');
set constraints all immediate;
reset role;
select is((select count(*) from komisio_private.seller_push_deliveries where kind='external_item_offered' and tenant_id=current_setting('test.tenant')::uuid),1::bigint,'committed offer and exact replay queue once');
select is((select count(*) from sellers where tenant_id=current_setting('test.tenant')::uuid),0::bigint,'push creates no seller');
select is((select count(*) from tenant_members where user_id='f7500000-0000-4000-8000-000000000002'),0::bigint,'push grants no membership');
select set_config('test.delivery',(select id::text from komisio_private.seller_push_deliveries where tenant_id=current_setting('test.tenant')::uuid),true);
set local role authenticated;
set local request.jwt.claims='{"sub":"f7500000-0000-4000-8000-000000000004","role":"authenticated"}';
select is((select value->>'ownerId' from jsonb_array_elements(seller_push_candidates()) where value->>'id'=current_setting('test.delivery')),'f7500000-0000-4000-8000-000000000002','worker candidates retain the explicit phone owner');
select is(claim_seller_push(current_setting('test.delivery')::uuid,'sv','Synthetic offer','Open the app')->>'requestId','f7500000-0000-4000-8000-000000000301','claim binds the phone-owned request');
select is(claim_seller_push(current_setting('test.delivery')::uuid,'sv','Synthetic offer','Open the app'),null::jsonb,'second claim cannot send again');
select finish_seller_push(current_setting('test.delivery')::uuid,'accepted','f7500000-0000-4000-8000-000000000501','');
select complete_seller_push_receipt(current_setting('test.delivery')::uuid,'sent','');
set local request.jwt.claims='{"sub":"f7500000-0000-4000-8000-000000000002","session_id":"f7500000-0000-4000-8000-000000000012","role":"authenticated"}';
select respond_external_item_offer('f7500000-0000-4000-8000-000000000601','f7500000-0000-4000-8000-000000000401',false,null);
reset role;
select is((select count(*) from komisio_private.seller_push_deliveries where tenant_id=current_setting('test.tenant')::uuid),1::bigint,'seller refusal does not masquerade as a store rejection');
set local role authenticated;
set local request.jwt.claims='{"sub":"f7500000-0000-4000-8000-000000000002","session_id":"f7500000-0000-4000-8000-000000000012","role":"authenticated"}';
select submit_external_item_request('f7500000-0000-4000-8000-000000000302',current_setting('test.tenant')::uuid,'Lamp','','good','',null,'SEK',array['f7500000-0000-4000-8000-000000000201']::uuid[],'SE','seller_amount');
set local request.jwt.claims='{"sub":"f7500000-0000-4000-8000-000000000001","role":"authenticated"}';
select decline_external_item_request('f7500000-0000-4000-8000-000000000402',current_setting('test.tenant')::uuid,'f7500000-0000-4000-8000-000000000302','Synthetic reason');
reset role;
select is((select count(*) from komisio_private.seller_push_deliveries where kind='external_item_declined' and tenant_id=current_setting('test.tenant')::uuid),1::bigint,'staff decline queues once');
select set_config('test.decline',(select id::text from komisio_private.seller_push_deliveries where kind='external_item_declined' and tenant_id=current_setting('test.tenant')::uuid),true);
set local role authenticated;
set local request.jwt.claims='{"sub":"f7500000-0000-4000-8000-000000000002","session_id":"f7500000-0000-4000-8000-000000000012","role":"authenticated"}';
select set_my_push_device('f7500000-0000-4000-8000-000000000021',repeat('a',64),gen_random_uuid(),1,null,'ios','sv',false);
set local request.jwt.claims='{"sub":"f7500000-0000-4000-8000-000000000004","role":"authenticated"}';
select is(claim_seller_push(current_setting('test.decline')::uuid,'sv','Synthetic decline','Open the app'),null::jsonb,'consent withdrawal cancels an unsent rejection');
reset role;
select is((select state from komisio_private.seller_push_deliveries where id=current_setting('test.decline')::uuid),'cancelled','cancellation is durable');
set local role authenticated;
set local request.jwt.claims='{"sub":"f7500000-0000-4000-8000-000000000002","session_id":"f7500000-0000-4000-8000-000000000012","role":"authenticated"}';
select submit_external_item_request('f7500000-0000-4000-8000-000000000303',current_setting('test.tenant')::uuid,'No backfill','','good','',null,'SEK',array['f7500000-0000-4000-8000-000000000201']::uuid[],'SE','seller_amount');
set local request.jwt.claims='{"sub":"f7500000-0000-4000-8000-000000000001","role":"authenticated"}';
select issue_external_item_offer(current_setting('test.tenant')::uuid,'f7500000-0000-4000-8000-000000000403','f7500000-0000-4000-8000-000000000303',null,40000,100000,'f7500000-0000-4000-8000-000000000101');
set local request.jwt.claims='{"sub":"f7500000-0000-4000-8000-000000000002","session_id":"f7500000-0000-4000-8000-000000000012","role":"authenticated"}';
select set_my_push_device('f7500000-0000-4000-8000-000000000021',repeat('a',64),gen_random_uuid(),2,'ExpoPushToken[synthetic_external]','ios','sv',true);
reset role;
select is((select count(*) from komisio_private.seller_push_deliveries where reference_id='f7500000-0000-4000-8000-000000000403'),0::bigint,'enabling consent does not backfill older offers');
set local role authenticated;
set local request.jwt.claims='{"sub":"f7500000-0000-4000-8000-000000000002","session_id":"f7500000-0000-4000-8000-000000000012","role":"authenticated"}';
select submit_external_item_request('f7500000-0000-4000-8000-000000000304',current_setting('test.tenant')::uuid,'Expired session','','good','',null,'SEK',array['f7500000-0000-4000-8000-000000000201']::uuid[],'SE','seller_amount');
set local request.jwt.claims='{"sub":"f7500000-0000-4000-8000-000000000001","role":"authenticated"}';
select decline_external_item_request('f7500000-0000-4000-8000-000000000404',current_setting('test.tenant')::uuid,'f7500000-0000-4000-8000-000000000304','Synthetic reason');
reset role;
select set_config('test.expired',(select id::text from komisio_private.seller_push_deliveries where reference_id='f7500000-0000-4000-8000-000000000404'),true);
update auth.sessions set not_after=now()-interval '1 hour' where id='f7500000-0000-4000-8000-000000000012';
set local role authenticated;
set local request.jwt.claims='{"sub":"f7500000-0000-4000-8000-000000000004","role":"authenticated"}';
select is(claim_seller_push(current_setting('test.expired')::uuid,'sv','Synthetic decline','Open app'),null::jsonb,'expired login cancels pending delivery');
select * from finish();
rollback;
